ight:1.1;margin-bottom:3px}.importRow{align-items:flex-start}}@media(max-width:350px){main{margin-left:9px;margin-right:9px}.tiles{gap:8px}.tile{padding:12px;min-height:172px}.tile span:not(.ico){font-size:13px}.metrics{gap:7px}.metric b{font-size:20px}}</style><script>if('scrollRestoration' in history)history.scrollRestoration='manual';function adminStartAtTop(){if(!location.hash)window.scrollTo(0,0)}window.addEventListener('pageshow',function(e){if(!location.hash){adminStartAtTop();requestAnimationFrame(adminStartAtTop);setTimeout(adminStartAtTop,80)}});</script></head><body><header class="top"><div class="topin"><div class="brand"><span class="logo">PS</span>Профи<i>Спорт</i></div><div class="menu">☰</div></div></header><main><section class="hero"><strong>Профи<i>Спорт</i></strong><span>Всё для активного отдыха</span></section><section class="metrics"><div class="metric"><small>Товаров</small><b id="statProducts">—</b><span class="delta">+0 сегодня</span></div><div class="metric"><small>Заказов</small><b id="statOrders">—</b><span class="delta">+0 сегодня</span></div><div class="metric"><small>Фотографий</small><b>19 137</b><span class="delta">в базе</span></div><div class="metric"><small>Категорий</small><b>277</b><span class="delta">актуально</span></div></section><h1 class="title">Управление магазином</h1><section class="tiles"><a class="tile primary" href="#catalog"><span class="ico"><svg viewBox="0 0 24 24"><path d="M4 7l8-4 8 4-8 4-8-4zM4 7v10l8 4 8-4V7M12 11v10"/></svg></span><b>Каталог из 1С</b><span>Импорт и обновление товаров</span><i class="arrow">→</i></a><a class="tile" href="#orders"><span class="ico"><svg viewBox="0 0 24 24"><circle cx="9" cy="20" r="1"/><circle cx="19" cy="20" r="1"/><path d="M3 4h2l2.4 11h11l2-7H6"/></svg></span><b>Заказы</b><span>Просмотр и обработка</span><i class="arrow">→</i></a><a class="tile" href="#products"><span class="ico"><svg viewBox="0 0 24 24"><path d="M20 13l-7 7-9-9V4h7l9 9z"/><circle cx="8.5" cy="8.5" r="1"/></sv